Definition TM : tree xi := Eval vm_compute in mk_tbl ASEGS 0x92454 2238.
Definition IMGR : list (Z * nat) := [(0xdcc10, 1%nat); (0xdcc68, 1%nat); (0x227f0, 32%nat); (0x10300, 0x30%nat); (0x229c0, 1302%nat); (0x25448, 0x2e%nat); (0x227d0, 4%nat); (0x11578, 2%nat)].
Definition IMGW : tree Z := Eval vm_compute in mk_imgs_acc IMGR TEmpty.
Definition F5 := lvar 22.
Definition R0 : tree lin := rsets (regs_pat 31 TEmpty) [(10, T); (11, TL); (12, V); (13, FMT); (14, lconst 42949673006); (15, lconst 0); (1, RA); (2, SP); (4, lconst TPV)].
Definition F0 : list fact :=
  [ FRange (lsub T (lscale 8 Y0)) 0 256; FRange (lsub (lscale 8 Y1) TL) 1 256; FRange (lsub Y1 Y0) 1 64; FRange L 1 128;
    FRange Y0 ((IMG_END - 256) / 8) (KTOP / 8); FRange Y1 ((IMG_END - 256) / 8) (KTOP / 8);
    FRange (laddc SP (-4288)) KHI (KTOP - 4288); FMod SP 5 0; FMod RA 1 0;
    FRange (lsub (laddc SP (-4288)) (laddc FS 0xb09000)) 0 KTOP;     (* [comment removed for export] *)
    FRange (lsub (laddc SP (-4288)) TL) 0 KTOP;                       (* [comment removed for export] *)
    FRange (lsub T (fsc AR4)) 0x200000 (2 ^ 64 - 128);                 (* [comment removed for export] *)
    FRange (lsub T (fsc 0x9000)) 0 (2 ^ 64 - 0x9000 - 256);            (* [comment removed for export] *)
    spsh_fact 4288; FRange SPSH (SHB + KHI / 8) (SHB + (KTOP - 4288) / 8);   (* [comment removed for export] *)
    FBits FMT 18446744073709551610 0; FRange FMT 1 5 ]
  ++ List.flat_map (fun '(X, n) => [FRange (lsub X (laddc SP 128)) 0 (2 ^ 64 - 4416 - n)]) [(CTX, 160); (THR, 80); (BLK, 32)]
  ++ two_class T 256 ++ v_facts ++ fks4_facts ++ rt_facts.
Definition RGS : list region :=
  [ RG T L RT TEmpty;                                    (* [comment removed for export] *)
    RG (ladd Y0 (lconst SHB)) (lsub Y1 Y0) RZ TEmpty;    (* [comment removed for export] *)
    RGz V 8 RW TEmpty;                                   (* [comment removed for export] *)
    RGz VS 1 RZ TEmpty;                                  (* [comment removed for export] *)
    RGz (laddc SP (-4096)) (4096 - 104) RW TEmpty;       (* [comment removed for export] *)
    RGz (laddc SP (-104)) 104 RW TEmpty;                 (* [comment removed for export] *)
    RGz (lconst 0x10000) 0x2e000 RO TEmpty;              (* [comment removed for export] *)
    track (RGz (lconst 0xe4db8) 12 RW TEmpty) 0 (bk8 SHB ++ bkn 4 1);  (* [comment removed for export] *)
    RGz (lconst (SHB + 0x44fe)) 32 RZ TEmpty;            (* [comment removed for export] *)
    RGz (lconst (SHB + 0x2060)) 0x30 RZ TEmpty;          (* [comment removed for export] *)
    RGz (lconst (SHB + 0x4538)) 1302 RZ TEmpty;          (* [comment removed for export] *)
    RGz (lconst (SHB + 0x4a89)) 0x2e RZ TEmpty;          (* [comment removed for export] *)
    RGz (lconst 0xe1278) 4 RO TEmpty ]                   (* [comment removed for export] *)
  ++ relro_rgs ++ fks4_split ++ fks5_whole ++ [fs_hdr] ++ rt_rgs
  ++ [ RGz SPSH 536 RZ TEmpty;                          (* [comment removed for export] *)
       fk3sh; tbl10sh; pow5tabsh ].                     (* [comment removed for export] *)
Definition P0 : sst := SST 0x92454 R0 RGS F0 200 RNone.
Definition NPCS : list Z := [0x924e0; 0x9292c; 0x92b04; 0x92b08; 0x92ca0; 0x92b2c; 0x92b54; 0x92bac; 0x93134; 0x92fe8; 0x93150; 0x93210; 0x9326c; 0x93274;
   0x92cec; 0x92d70; 0x92dd0; 0x9304c; 0x93084; 0x930d0; 0x92fb4; 0x93da8; 0x93dc0; 0x943cc;
   0x932a8; 0x932b4; 0x9333c; 0x937e0; 0x93728; 0x93378; 0x934dc; 0x93578; 0x93544; 0x936dc; 0x93ca8; 0x93cf8; 0x939c8; 0x93a04; 0x93a34;
   0x93680; 0x93714; 0x9378c; 0x9380c; 0x93858; 0x93860; 0x9395c].
Definition CALLS : list Z := [0x4ad74; 0x60650; 0x93b3c; 0x63e2c; 0x63d24; 0x691c8].
Definition ALLST : list Z := NPCS ++ CALLS.
Definition ANC : list lin := [T; TL].
Definition PR : plan := PRun 400 ALLST [].
Definition RELS : list (list (Z * Z)) := [[(10, 1); (22, -1)]; [(5, 1); (10, -1); (22, 1); (12, -1)]; [(12, 1); (13, 1)]; [(1, 1); (10, -1); (22, 1)]; [(23, 1); (10, -1); (12, -1)]].
Definition JR (Ls : list sst) : sst := rjoin_r 200 ANC [] RELS Ls.
Definition XNJ (pc : Z) : Z * xaction := (pc, xjoin JR (fun _ => PR)).
Definition FRKEY (L : sst) : Z :=
  match find_cell (s_rgs L) (laddc (rgl L 9) 40) with Some (_, _, l) => if lin_eqb l (lconst 0) then 0 else 1 | None => 2 end.
Definition XNFR (pc : Z) : Z * xaction := (pc, xjoin_part FRKEY JR (fun _ => PR)).
Definition XNLF (pc : Z) : Z * xaction := (pc, xjoin_part FRKEY JR (aloop TM IMGW ANC 400 ALLST)).
Definition XNJF (pc : Z) (ks : list Z) : Z * xaction := (pc, xjoin (rjoin_gck 200 ANC (List.map rk ks)) (fun _ => PR)).
Definition XNL (pc : Z) : Z * xaction := (pc, xjoin (rjoin_gc 200 ANC) (aloop TM IMGW ANC 400 ALLST)).
Definition TMKEY2 (L : sst) : Z :=
  match nth_error (s_rgs L) 20 with
  | Some R => match tget (okey 634) (rg_cont R), tget (okey 633) (rg_cont R) with Some (BK b), Some (BK v) => 2 * b + v | _, _ => -1 end
  | None => -1
  end.
Definition XNT (pc : Z) : Z * xaction := (pc, xjoin_part TMKEY2 JR (fun _ => PR)).
Definition JRF (ks : list Z) (Ls : list sst) : sst := rjoin_r 200 ANC (List.map rk ks) RELS Ls.
Definition XNTK (pc : Z) (ks : list Z) : Z * xaction := (pc, xjoin_part TMKEY2 (JRF ks) (fun _ => PR)).
Definition MSV (o n : Z) : list (vop * Z * rkind) :=
  [(VSub 4 1696, 2208, RW); (VSub 20 o, n, RW); (VSub 23 (ms_lo8 o), ms_hsz o n, RW); (VCopy 7, 0, RW)] ++ List.map (fun i => (VCopy i, 0, RW)) (seq 30 11) ++ [(VCopy 13, 0, RO); (VCopy 14, 0, RO)].
Definition CS_MS32 : csite := mk_csite MEMSET32_P0 MEMSET32_Q KEEPK [] (MSV 640 32).
Definition CS_MS27 : csite := mk_csite MEMSET27_P0 MEMSET27_Q KEEPK [] (MSV 608 27).
Definition XMS : Z * xaction := (0x60650, XCallKs [CS_MS32; CS_MS27]).
Definition XF11 : Z * xaction := (0x60650, XHand (hx_fold 0x60650 11)).
Definition RET1 : list Z := [0x92910; 0x92ae0; 0x92db8; 0x92f84; 0x92fd0; 0x930e4; 0x9328c; 0x94128; 0x94204; 0x94238].
Definition RET2 : list Z := [0x92920; 0x92af0; 0x92dc8; 0x92f94; 0x92fe0; 0x930f4; 0x9329c; 0x94138; 0x94214; 0x94248].
Definition A0KEY (L : sst) : Z := match is_const (rgl L 10) with Some c => c | None => -1 end.
Definition XNA (pc : Z) : Z * xaction := (pc, xjoin_part A0KEY JR (fun _ => PR)).
Definition TMKEY (L : sst) : Z :=
  match nth_error (s_rgs L) 20 with Some R => match tget (okey 634) (rg_cont R) with Some (BK b) => b | _ => -1 end | None => -1 end.
Definition XNP (pc : Z) : Z * xaction := (pc, xjoin_part TMKEY (rjoin_gc 200 ANC) (fun _ => PR)).
Definition XNPF (pc : Z) (ks : list Z) : Z * xaction := (pc, xjoin_part TMKEY (rjoin_gck 200 ANC (List.map rk ks)) (fun _ => PR)).
(* [comment removed for export] *)
Definition XNS (pc : Z) : Z * xaction := (pc, xjoin_each JR (fun _ => PR)).
Definition SM4 : Z * waction := (0x4ad74, WHand (smalloc_cont 4 15 17 20 23 1024 SLOT4 FLB4)).
Definition CS_SM4 : csite := mk_csite SM4_P0 SM4_Q KEEPK SM4_QK
  ([(VCopy 4, 0, RW); (VCopy 15, 0, RW); (VCopy 16, 0, RZ); (VCopy 17, 0, RZ); (VCopy 18, 0, RZ); (VCopy 20, 0, RW); (VCopy 23, 0, RW); (VCopy 29, 0, RW); (VCopy 7, 0, RW)]
   ++ List.map (fun i => (VCopy i, 0, RW)) (seq 30 11) ++ [(VCopy 13, 0, RO); (VCopy 14, 0, RO)]).
Definition KC (k : Z) (L : sst) : Z := match is_const (rgl L k) with Some c => c | None => 4095 end.
Definition QKEY (L : sst) : Z :=
  let w := irange_pre (s_facts L) (rgl L 26) in
  if (Z.leb (-342) (fst w) && Z.leb (snd w) 308)%bool then 0 else if Z.ltb (snd w) (-342) then 1 else if Z.ltb 308 (fst w) then 2 else 3.
Definition FRK2 (L : sst) : Z :=
  match nth_error (s_rgs L) 20 with
  | Some R => match tget (okey 656) (rg_cont R) with Some (BK 0) => 0 | Some (BV _ _) => 1 | _ => 2 end
  | None => 2
  end.
Definition XNK1 (pc : Z) : Z * xaction := (pc, xjoin_part (fun L => 2 ^ 30 * FRK2 L + 2 ^ 28 * QKEY L + 2 ^ 24 * TMKEY2 L + 4096 * KC 27 L + KC 23 L) JR (fun _ => PR)).
Definition XNK2 (pc : Z) : Z * xaction := (pc, xjoin_part (fun L => 2 ^ 42 * FRK2 L + 2 ^ 40 * QKEY L + 2 ^ 36 * KC 27 L + 2 ^ 24 * KC 23 L + 4096 * KC 10 L + KC 13 L) JR (fun _ => PR)).
Definition XNAF (pc : Z) : Z * xaction := (pc, xjoin_part (fun L => 4 * FRKEY L + A0KEY L) JR (fun _ => PR)).
Definition XNTF (pc : Z) : Z * xaction := (pc, xjoin_part (fun L => 4 * FRK2 L + TMKEY2 L) JR (fun _ => PR)).
Definition XNTKF (pc : Z) (ks : list Z) : Z * xaction := (pc, xjoin_part (fun L => 4 * FRK2 L + TMKEY2 L) (JRF ks) (fun _ => PR)).
Definition XNF (pc : Z) : Z * xaction := (pc, xjoin_part FRK2 JR (fun _ => PR)).
Definition XF10 : Z * xaction := (0x943cc, XHand (hx_fold 0x943cc 10)).
Definition DCFV : list (vop * Z * rkind) :=
  [(VCopy 0, 0, RT); (VCopy 1, 0, RZ); (VSub 4 1136, 2768, RW); (VSub 41 178, 345, RZ); (VSub 20 32, 984, RW); (VCopy 23, 0, RW);
   (VCopy 15, 0, RW); (VCopy 16, 0, RZ); (VCopy 17, 0, RZ); (VCopy 18, 0, RZ); (VCopy 19, 0, RW); (VCopy 21, 0, RW); (VCopy 22, 0, RW);
   (VCopy 24, 0, RW); (VCopy 42, 0, RW); (VCopy 25, 0, RW); (VCopy 26, 0, RZ); (VCopy 27, 0, RW); (VCopy 28, 0, RW); (VCopy 29, 0, RW);
   (VCopy 7, 0, RW)] ++ List.map (fun i => (VCopy i, 0, RW)) (seq 30 11) ++
  [(VCopy 13, 0, RO); (VCopy 14, 0, RO); (VCopy 6, 0, RO); (VCopy 43, 0, RZ); (VCopy 44, 0, RZ); (VSub 4 3984, 8, RW)].
Definition CS_DCF (frac : bool) : csite := mk_csite (DCF_P0 frac) (DCF_Q frac) KEEPFK [] DCFV.
Definition SSV : list (vop * Z * rkind) := [(VSub 4 3840, 64, RW); (VCopy 23, 0, RW); (VCopy 13, 0, RO); (VCopy 14, 0, RO)].
Definition CS_SSF5 : csite := mk_csite SSF5_P0 SSF5_Q KEEPK [] SSV.
Definition NODES5 : list (Z * xaction) :=
  [XF10; XNAF 0x943cc; XNTF 0x932a8; XNTKF 0x9333c [26]; XNTF 0x937e0; XNTKF 0x93728 [26]; XNTF 0x932b4; XNTF 0x93378; XNTF 0x934dc; XNK1 0x93544;
   XNF 0x93578; XNF 0x93680; XNF 0x936dc; XNF 0x93714; XNF 0x9378c; XNF 0x9380c; XNK2 0x93858; XNF 0x93860; XNF 0x9395c;
   XNF 0x939c8; XNF 0x93a04; XNF 0x93a34; (0x93b3c, XFragKs [CS_DCF true; CS_DCF false] 0x93b98); XNJ 0x93b98;
   XNJ 0x93ca8; XNJ 0x93cf8; (0x63e2c, XCallK CS_SSF5); XNJ 0x93d3c; (0x93d98, XHand (hx_promote 0x93d98 17))].
Definition SPD_QRGS : list region :=
  map_i (fun i R => if Nat.eqb i 15 then RGz (fsc 32) 8 RW TEmpty
                    else if Nat.eqb i 25 then RGz (fsc 40) 8 RW TEmpty else R) 0 RGS.
Definition SPD_Q : sst := SST 0 (regs_keep R0 31 200 TEmpty) SPD_QRGS F0 250 RNone.
Definition NODES1 : list (Z * xaction) :=
  [(0x4ad74, XCallK CS_SM4); XNJ 0x924e0; (0x9292c, XHand H_INT); XNJ 0x92b04; (0x92b08, XHand H_DOT);
   (0x92ca0, XHand R_NOFRAC); XNJ 0x92ca0; XNJ 0x92b2c; (0x92b54, XHand R_DIG0); XNJ 0x92b54;
   (0x92bac, XHand H_SW8); XNS 0x93134; XNS 0x92fe8; (0x93150, XHand H_SW4); (0x93210, XHand H_BYTE); XNS 0x9326c;
   (0x93274, XHand R_FRAC); XNJ 0x93274;
   XNFR 0x92cec; XNFR 0x92d70; XNFR 0x9304c; XNLF 0x93084; XNFR 0x930d0; XNFR 0x92fb4; XNFR 0x93da8; (0x93dc0, XHand H_TM)]
  ++ ([XF11; XMS] ++ List.map XNJ RET1 ++ [XF11; XMS] ++ List.map XNJ RET2).
Definition NODES : list (Z * xaction) := NODES1 ++ NODES5.
Definition P0RUN : plan := PRun 300 ALLST [].
